<script setup>
import { computed, h, ref } from 'vue';
import { Link, router, useForm, usePage } from '@inertiajs/vue3';
import AppShell from '@/Layouts/AppShell.vue';

defineOptions({ layout: (_h, page) => h(AppShell, { active: 'imports' }, () => page) });
const props = defineProps({ sources: Array, runs: Array, items: Object, filters: Object, reports: Array, claims: Array, deliveryHealth: Array, uncertainDeliveries: Array });
const page = usePage();
const editingSource = ref(null);
const domainText = ref('');
const sourceForm = useForm({ key: '', name: '', provider: 'jsonld', url: '', allowed_domains: [], permission_status: 'pending', permission_notes: '', publication_mode: 'review', enabled: false, company_id: null, cadence_hours: 24, request_delay_ms: 1000, max_requests: 100, settings: { employer_name: '', job_path_prefix: '', authoritative_employer: false, scope: 'all' } });
const editSource = (source) => {
    editingSource.value = source.id;
    for (const key of Object.keys(sourceForm.data())) sourceForm[key] = source[key];
    sourceForm.settings = { employer_name: '', job_path_prefix: '', authoritative_employer: false, scope: 'all', ...(source.settings || {}) };
    domainText.value = source.allowed_domains.join(', ');
};
const resetSource = () => { editingSource.value = null; sourceForm.reset(); domainText.value = ''; };
const saveSource = () => {
    sourceForm.allowed_domains = [...new Set(domainText.value.split(/[\s,]+/).map((part) => part.trim().toLowerCase()).filter(Boolean))];
    const options = { preserveScroll: true, onSuccess: resetSource };
    editingSource.value ? sourceForm.put(route('imports.sources.update', editingSource.value), options) : sourceForm.post(route('imports.sources.store'), options);
};
const toggleSource = (source) => router.put(route('imports.sources.update', source.id), { ...source, enabled: !source.enabled }, { preserveScroll: true });
const queue = (source, recheck = false) => router.post(route('imports.sources.run', source.id), { recheck }, { preserveScroll: true });
const publish = (item) => router.post(route('imports.items.publish', item.id), {}, { preserveScroll: true });
const rejection = useForm({ reason: '' });
const rejectingId = ref(null);
const reject = () => rejection.post(route('imports.items.reject', rejectingId.value), { preserveScroll: true, onSuccess: () => { rejectingId.value = null; rejection.reset(); } });
const moderation = useForm({ action: 'suppress', reason: '', corrections: {} });
const moderationId = ref('');
const correctionField = ref('remote_eligibility');
const correctionValue = ref('unknown');
const correctionOptions = computed(() => ({ remote_eligibility: ['eligible', 'restricted', 'unknown'], relocation: ['yes', 'no', 'unknown'], visa_sponsorship: ['yes', 'no', 'unknown'], kind: ['internship', 'job'] }[correctionField.value] || null));
const moderate = () => { moderation.corrections = moderation.action === 'correct' ? { [correctionField.value]: correctionValue.value } : {}; moderation.put(route('imports.opportunities.moderate', moderationId.value), { preserveScroll: true }); };
const mergeForm = useForm({ survivor_id: '', reason: '' });
const duplicateId = ref('');
const merge = () => mergeForm.post(route('imports.opportunities.merge', duplicateId.value), { preserveScroll: true, onSuccess: () => { duplicateId.value = ''; mergeForm.reset(); } });
const reportNotes = ref({});
const claimNotes = ref({});
const resolveReport = (report, status) => router.put(route('imports.reports.resolve', report.id), { status, notes: reportNotes.value[report.id] || '' }, { preserveScroll: true });
const reviewClaim = (claim, status) => router.put(route('imports.claims.review', claim.id), { status, review_notes: claimNotes.value[claim.id] || '' }, { preserveScroll: true });
const date = (value) => value ? String(value).replace('T', ' ').slice(0, 16) + ' UTC' : 'Not yet';
</script>

<template>
    <div class="max-w-[1400px] mx-auto px-5 md:px-10 py-9 space-y-8">
        <header><p class="text-blue-600 uppercase text-xs tracking-widest font-semibold">Catalogue operations</p><h1 class="font-display text-3xl font-semibold mt-2">Sources and moderation</h1><p class="text-muted mt-2">Review source permissions, import health, opportunity facts, reports, and employer claims.</p></header>
        <div v-if="Object.keys(page.props.errors || {}).length" class="bg-red-50 border border-red-200 text-red-700 rounded-xl p-4" role="alert"><p v-for="(error, key) in page.props.errors" :key="key">{{ error }}</p></div>
        <section class="space-y-4" aria-labelledby="source-heading">
            <h2 id="source-heading" class="font-display text-2xl font-semibold">Source registry</h2>
            <p v-if="!sources.length" class="text-muted">No sources are configured. Add a permitted employer board or agreed feed to begin.</p>
            <div class="grid xl:grid-cols-2 gap-4">
                <article v-for="source in sources" :key="source.id" class="bg-white border border-line rounded-2xl p-5">
                    <div class="flex justify-between gap-4"><div><h3 class="font-semibold text-lg">{{ source.name }}</h3><p class="text-xs text-muted mt-1">{{ source.provider }} · {{ source.permission_status }} · {{ source.enabled ? 'Enabled' : 'Paused' }} · {{ source.publication_mode }}</p></div><button class="text-blue-600 font-semibold" @click="editSource(source)">Edit</button></div>
                    <p class="text-sm break-all mt-3">{{ source.url }}</p><p class="text-sm mt-2">{{ source.items_count }} discovered items · {{ source.pending_count }} pending or awaiting review</p>
                    <p class="text-xs text-muted mt-2">Last complete discovery: {{ date(source.last_complete_at) }}. Every {{ source.cadence_hours }} hours.</p>
                    <p v-if="source.last_error" class="text-red-700 text-sm mt-3">{{ source.last_error }}</p>
                    <div class="flex flex-wrap gap-4 mt-4 text-sm font-semibold"><button @click="toggleSource(source)" :disabled="!source.enabled && source.permission_status !== 'approved'" class="disabled:opacity-40">{{ source.enabled ? 'Pause source' : 'Enable source' }}</button><button @click="queue(source)" :disabled="!source.enabled || source.permission_status !== 'approved'" class="text-blue-600 disabled:opacity-40">Run import</button><button @click="queue(source, true)" :disabled="!source.enabled || source.permission_status !== 'approved'" class="text-blue-600 disabled:opacity-40">Recheck source</button></div>
                </article>
            </div>
            <details class="bg-white border border-line rounded-2xl p-5" :open="Boolean(editingSource)">
                <summary class="cursor-pointer font-semibold">{{ editingSource ? 'Edit source' : 'Add a source' }}</summary>
                <form class="mt-5 space-y-4" @submit.prevent="saveSource">
                    <div class="grid md:grid-cols-3 gap-4">
                        <label class="text-sm font-semibold">Name<input v-model="sourceForm.name" class="fld mt-2" required></label><label class="text-sm font-semibold">Stable source key<input v-model="sourceForm.key" class="fld mt-2" required placeholder="company-greenhouse"></label><label class="text-sm font-semibold">Provider<select v-model="sourceForm.provider" class="fld mt-2"><option value="jsonld">Public pages with JSON-LD</option><option value="greenhouse">Greenhouse</option><option value="lever">Lever</option><option value="ashby">Ashby</option></select></label>
                        <label class="text-sm font-semibold md:col-span-2">Feed, board API, or sitemap URL<input v-model="sourceForm.url" class="fld mt-2" type="url" required></label><label class="text-sm font-semibold">Allowed domains<input v-model="domainText" class="fld mt-2" required placeholder="boards-api.greenhouse.io, example.com"></label>
                        <label class="text-sm font-semibold">Reuse permission<select v-model="sourceForm.permission_status" class="fld mt-2"><option value="pending">Pending review</option><option value="approved">Approved for the intended reuse</option><option value="revoked">Revoked</option></select></label><label class="text-sm font-semibold">Publication<select v-model="sourceForm.publication_mode" class="fld mt-2"><option value="review">Review every new opportunity</option><option value="automatic">Publish validated opportunities automatically</option></select></label><label class="text-sm font-semibold">Verified company ID, optional<input v-model.number="sourceForm.company_id" class="fld mt-2" type="number" min="1"></label>
                        <label class="text-sm font-semibold md:col-span-3">Permission evidence and review notes<textarea v-model="sourceForm.permission_notes" class="fld mt-2" rows="3" placeholder="Record the agreement, source URL, scope of reuse, and review date. Robots access alone does not grant republication rights."></textarea></label>
                        <label class="text-sm font-semibold">Cadence, hours<input v-model.number="sourceForm.cadence_hours" class="fld mt-2" type="number" min="1" max="168" required></label><label class="text-sm font-semibold">Delay between requests, milliseconds<input v-model.number="sourceForm.request_delay_ms" class="fld mt-2" type="number" min="500" max="60000" required></label><label class="text-sm font-semibold">Maximum requests per run<input v-model.number="sourceForm.max_requests" class="fld mt-2" type="number" min="1" max="1000" required></label>
                        <label class="text-sm font-semibold">Employer name supplied by this board<input v-model="sourceForm.settings.employer_name" class="fld mt-2"></label><label class="text-sm font-semibold">Job URL path prefix, optional<input v-model="sourceForm.settings.job_path_prefix" class="fld mt-2" placeholder="/careers/jobs/"></label><label class="text-sm font-semibold">Listings to keep<select v-model="sourceForm.settings.scope" class="fld mt-2"><option value="all">Everything this source lists</option><option value="reachable">Internships, plus jobs open to people in Tunisia</option></select></label>
                    </div>
                    <label class="flex gap-2 items-start text-sm"><input v-model="sourceForm.settings.authoritative_employer" type="checkbox" class="mt-1"> This is the employer's authoritative board. Confirmed closure takes precedence over aggregator copies.</label>
                    <label class="flex gap-2 items-center text-sm"><input v-model="sourceForm.enabled" type="checkbox"> Enable scheduled imports once reuse permission is approved</label>
                    <div class="flex gap-4"><button class="cbtn bg-blue-600 text-white" :disabled="sourceForm.processing">Save source</button><button v-if="editingSource" type="button" @click="resetSource">Cancel edit</button></div>
                </form>
            </details>
        </section>
        <section class="space-y-4" aria-labelledby="review-heading">
            <h2 id="review-heading" class="font-display text-2xl font-semibold">Discovered opportunities</h2>
            <form method="get" :action="route('imports.index')" class="flex flex-wrap gap-3"><select name="source_id" class="fld !w-auto" :value="filters.source_id || ''"><option value="">All sources</option><option v-for="source in sources" :key="source.id" :value="source.id">{{ source.name }}</option></select><select name="state" class="fld !w-auto" :value="filters.state || ''"><option value="">All states</option><option v-for="state in ['pending','review','published','closed','rejected']" :key="state">{{ state }}</option></select><button class="cbtn border border-line bg-white">Filter</button></form>
            <p v-if="!items.data.length" class="text-muted">No discovered items match these filters.</p>
            <article v-for="item in items.data" :key="item.id" class="bg-white border border-line rounded-2xl p-5">
                <div class="flex flex-wrap justify-between gap-3"><h3 class="font-semibold">{{ item.normalized_data?.title || item.internship?.title || 'Pending extraction' }}</h3><span class="text-xs text-muted">Item {{ item.id }} · {{ item.state }}<template v-if="item.internship"> · Opportunity {{ item.internship.id }}</template></span></div>
                <p class="text-sm text-muted mt-2">{{ item.source_name }} · Last verified {{ date(item.last_verified_at) }}</p><a :href="item.source_url" target="_blank" rel="noopener noreferrer" class="text-sm text-blue-600 break-all">View original source</a>
                <p v-if="item.error" class="text-red-700 text-sm mt-3">{{ item.error }}</p>
                <details v-if="item.normalized_data" class="mt-3"><summary class="text-sm font-semibold cursor-pointer">Review extracted facts and description</summary><p class="text-xs text-muted mt-3">{{ item.normalized_data.employer }} · {{ item.normalized_data.kind }} · {{ item.normalized_data.location || 'Location unspecified' }} · Remote eligibility: {{ item.normalized_data.remote_eligibility }}</p><p class="text-xs text-muted mt-1">Relocation: {{ item.normalized_data.relocation }} · Visa sponsorship: {{ item.normalized_data.visa_sponsorship }}</p><p class="whitespace-pre-wrap text-sm leading-6 mt-4 max-h-[420px] overflow-auto">{{ item.normalized_data.description }}</p><pre class="whitespace-pre-wrap break-words text-xs mt-3">{{ item.normalized_data.eligibility_evidence }}</pre></details>
                <div class="flex flex-wrap gap-4 text-sm font-semibold mt-4"><button v-if="item.normalized_data && item.state !== 'closed'" class="text-blue-600" @click="publish(item)">Approve publication</button><a v-if="item.internship?.publication_status === 'published'" class="text-blue-600" :href="item.internship.public_url">Open page</a><button v-if="item.internship" @click="moderationId = item.internship.id">Select for correction</button><button class="text-red-600" @click="rejectingId = item.id">Reject source item</button></div>
                <form v-if="rejectingId === item.id" class="mt-4 flex flex-wrap gap-3" @submit.prevent="reject"><label class="grow text-sm">Reason<input v-model="rejection.reason" class="fld mt-1" minlength="5" required></label><button class="cbtn border border-red-200 text-red-600 self-end" :disabled="rejection.processing">Reject</button></form>
            </article>
            <nav class="flex flex-wrap gap-2" aria-label="Imported items pagination"><template v-for="(link, index) in items.links" :key="index"><Link v-if="link.url" :href="link.url" class="px-3 py-2 rounded-lg text-sm border" :class="link.active ? 'border-blue-600 text-blue-700' : 'border-line'" :aria-current="link.active ? 'page' : undefined" v-html="link.label" /><span v-else class="px-3 py-2 rounded-lg text-sm border border-line opacity-40" aria-disabled="true" v-html="link.label" /></template></nav>
        </section>
        <section class="grid lg:grid-cols-2 gap-5">
            <form class="bg-white border border-line rounded-2xl p-5 space-y-4" @submit.prevent="moderate"><h2 class="font-display text-xl font-semibold">Correct or suppress an opportunity</h2><label class="block text-sm font-semibold">Opportunity ID<input v-model="moderationId" class="fld mt-2" type="number" min="1" required></label><label class="block text-sm font-semibold">Action<select v-model="moderation.action" class="fld mt-2"><option value="suppress">Suppress from public discovery</option><option value="close">Mark confirmed closed</option><option value="restore">Restore a suppressed page</option><option value="correct">Correct a source fact</option></select></label><template v-if="moderation.action === 'correct'"><label class="block text-sm font-semibold">Fact<select v-model="correctionField" class="fld mt-2" @change="correctionValue = correctionOptions?.[0] || ''"><option v-for="field in ['remote_eligibility','relocation','visa_sponsorship','kind','title','description','country_code','location']" :key="field">{{ field }}</option></select></label><label class="block text-sm font-semibold">Reviewed value<select v-if="correctionOptions" v-model="correctionValue" class="fld mt-2"><option v-for="value in correctionOptions" :key="value">{{ value }}</option></select><textarea v-else v-model="correctionValue" class="fld mt-2" required></textarea></label></template><label class="block text-sm font-semibold">Evidence and reason<textarea v-model="moderation.reason" class="fld mt-2" required minlength="5"></textarea></label><button class="cbtn bg-blue-600 text-white" :disabled="moderation.processing">Save moderation</button></form>
            <form class="bg-white border border-line rounded-2xl p-5 space-y-4" @submit.prevent="merge"><h2 class="font-display text-xl font-semibold">Merge a confirmed duplicate</h2><p class="text-sm text-muted">The employer identity must match. Keep the employer-managed listing as the survivor. Old URLs redirect and candidate history is retained.</p><label class="block text-sm font-semibold">Duplicate opportunity ID<input v-model="duplicateId" class="fld mt-2" type="number" min="1" required></label><label class="block text-sm font-semibold">Surviving opportunity ID<input v-model.number="mergeForm.survivor_id" class="fld mt-2" type="number" min="1" required></label><label class="block text-sm font-semibold">Why these are the same role<textarea v-model="mergeForm.reason" class="fld mt-2" required minlength="10"></textarea></label><button class="cbtn border border-line" :disabled="mergeForm.processing">Merge and preserve history</button></form>
        </section>
        <section class="space-y-4"><h2 class="font-display text-2xl font-semibold">Open reports</h2><p v-if="!reports.length" class="text-muted">No open reports.</p><article v-for="report in reports" :key="report.id" class="bg-white border border-line rounded-2xl p-5"><h3 class="font-semibold">{{ report.title }} · Opportunity {{ report.internship_id }}</h3><p class="text-sm mt-2">{{ report.reason }}: {{ report.details }}</p><label class="block text-sm mt-3">Review outcome<textarea v-model="reportNotes[report.id]" class="fld mt-2" rows="2"></textarea></label><div class="flex gap-4 mt-3 text-sm font-semibold"><button class="text-blue-600" @click="moderationId = report.internship_id">Select for moderation</button><button @click="resolveReport(report, 'resolved')">Resolve</button><button @click="resolveReport(report, 'dismissed')">Dismiss</button></div></article></section>
        <section class="space-y-4"><h2 class="font-display text-2xl font-semibold">Employer claims</h2><p v-if="!claims.length" class="text-muted">No claims awaiting review.</p><article v-for="claim in claims" :key="claim.id" class="bg-white border border-line rounded-2xl p-5"><h3 class="font-semibold">{{ claim.company_name || `Company ${claim.company_id}` }}</h3><p class="text-sm mt-2">Requested by {{ claim.claimant_name }} ({{ claim.claimant_email }})</p><p class="text-sm whitespace-pre-wrap mt-2">{{ claim.evidence }}</p><label class="block text-sm mt-3">Identity verification and decision notes<textarea v-model="claimNotes[claim.id]" class="fld mt-2" rows="3" placeholder="Record independent proof that this account is authorized to represent the employer."></textarea></label><div class="flex gap-4 mt-3 text-sm font-semibold"><button class="text-blue-600" @click="reviewClaim(claim, 'approved')">Approve verified claim</button><button class="text-red-600" @click="reviewClaim(claim, 'rejected')">Reject claim</button></div></article></section>
        <section><h2 class="font-display text-2xl font-semibold mb-4">Recent import runs</h2><div class="overflow-auto bg-white border border-line rounded-2xl"><table class="w-full text-left text-sm"><thead><tr class="border-b border-line"><th class="p-4">Source</th><th class="p-4">Status</th><th class="p-4">Discovered / processed / published</th><th class="p-4">Started</th><th class="p-4">Error</th></tr></thead><tbody><tr v-for="run in runs" :key="run.id" class="border-b border-line"><td class="p-4">{{ run.import_source?.name }}</td><td class="p-4">{{ run.status }} · {{ run.complete ? 'Complete discovery' : 'Partial or failed discovery' }}</td><td class="p-4">{{ run.discovered }} / {{ run.processed }} / {{ run.published }}</td><td class="p-4 whitespace-nowrap">{{ date(run.started_at) }}</td><td class="p-4 min-w-[180px]">{{ run.error }}</td></tr><tr v-if="!runs.length"><td colspan="5" class="p-5 text-muted">No runs yet.</td></tr></tbody></table></div></section>
        <section><h2 class="font-display text-2xl font-semibold mb-3">Email delivery health</h2><div class="flex flex-wrap gap-3"><span v-for="state in deliveryHealth" :key="state.status" class="bg-white border border-line px-4 py-2 rounded-lg text-sm">{{ state.status }}: {{ state.total }}</span><p v-if="!deliveryHealth.length" class="text-muted">No delivery attempts.</p></div><article v-for="batch in uncertainDeliveries" :key="batch.batch_id" class="mt-3 rounded-xl bg-amber-50 border border-amber-200 p-4 text-sm"><p class="font-semibold">Review uncertain batch {{ batch.batch_id }}</p><p class="mt-1">{{ batch.last_error }}</p><p class="mt-2">Check the mail provider, then run <code>php artisan opportunities:review-digest {{ batch.batch_id }}</code> with the confirmed outcome. Automatic retries are paused for this search.</p></article></section>
    </div>
</template>
